def rich_lesson(title, explain, rule, example, task, question, options, answer,
                steps, common_mistake, extra_task=None):
    # Some expanded lessons omit the separate practice-task argument. In that
    # older form, the quiz options land in `question` and the answer index in
    # `options`; shift those values back into their intended fields.
    if isinstance(options, int) and isinstance(question, list) and isinstance(answer, list):
        task, question, options, answer, steps, common_mistake, extra_task = (
            "Склади власний приклад і поясни, як у ньому застосовується правило.",
            task,
            question,
            options,
            answer,
            steps,
            common_mistake,
        )
    item = lesson(title, explain, example, task, question, options, answer)
    item.update({
        "rule": rule,
        "steps": steps,
        "common_mistake": common_mistake,
        "extra_task": extra_task,
    })
    return item


