def _short(text, limit=145):
    first = text.split(". ", 1)[0].strip()
    if len(first) > limit:
        first = first[:limit - 1].rsplit(" ", 1)[0] + "…"
    return first


def _question(prompt, candidates, seed):
    """Candidates are (answer_text, is_correct); shuffle choices reproducibly."""
    choices = list(candidates)
    Random(seed).shuffle(choices)
    return {
        "question": prompt,
        "options": [text for text, _is_correct in choices],
        "answer": next(i for i, (_text, is_correct) in enumerate(choices) if is_correct),
    }


def add_control_works():
    for grade, subjects in GRADES.items():
        for subject in subjects:
            lessons = subject["lessons"]
            guide = STUDY_GUIDES.get(grade, {}).get(subject["slug"])
            for index, item in enumerate(lessons):
                previous = lessons[index - 1] if index > 0 else lessons[-1]
                following = lessons[index + 1] if index + 1 < len(lessons) else lessons[0]
                seed = f"{grade}:{subject['slug']}:{index}"
                item["study_guide"] = guide or []
                rule = item.get("rule") or _short(item["explain"])
                previous_rule = previous.get("rule") or _short(previous["explain"])
                following_rule = following.get("rule") or _short(following["explain"])
                control_work = [
                    _question(item["question"], [(option, i == item["answer"]) for i, option in enumerate(item["options"])], seed + ":0"),
                    _question("Яке правило або пояснення стосується цієї теми?", [(rule, True), (previous_rule, False), (following_rule, False)], seed + ":1"),
                    _question("Який приклад наведено до цієї теми?", [(item["example"], True), (previous["example"], False), (following["example"], False)], seed + ":2"),
                    _question("Яке завдання допоможе закріпити матеріал цієї теми?", [(item["task"], True), (previous["task"], False), (following["task"], False)], seed + ":3"),
                    _question("Яка назва відповідає темі уроку?", [(item["title"], True), (previous["title"], False), (following["title"], False)], seed + ":4"),
                ]
                if grade >= 8:
                    item_steps = item.get("steps") or [item["rule"]]
                    previous_steps = previous.get("steps") or [previous.get("rule", previous["explain"])]
                    following_steps = following.get("steps") or [following.get("rule", following["explain"])]
                    item_mistake = item.get("common_mistake") or "Не пропускай пояснення кроків."
                    previous_mistake = previous.get("common_mistake") or previous["explain"]
                    following_mistake = following.get("common_mistake") or following["explain"]
                    item_extra = item.get("extra_task") or item["task"]
                    previous_extra = previous.get("extra_task") or previous["task"]
                    following_extra = following.get("extra_task") or following["task"]
                    more = [
                        ("З якого кроку варто почати цю тему?", item_steps[0], previous_steps[0], following_steps[0]),
                        ("Який крок допомагає завершити й перевірити роботу?", item_steps[-1], previous_steps[-1], following_steps[-1]),
                        ("Яка помилка особливо важлива для цієї теми?", item_mistake, previous_mistake, following_mistake),
                        ("Яке завдання для поглиблення пов’язане з цією темою?", item_extra, previous_extra, following_extra),
                        ("Яке ключове поняття назване в темі?", item["title"], previous["title"], following["title"]),
                        ("Яке твердження правильно підсумовує правило теми?", rule, previous_rule, following_rule),
                        ("Яке навчальне пояснення стосується саме цієї теми?", item["explain"], previous["explain"], following["explain"]),
                    ]
                    for question_number, (prompt, answer, distractor_a, distractor_b) in enumerate(more, start=5):
                        control_work.append(_question(prompt, [(answer, True), (distractor_a, False), (distractor_b, False)], seed + f":{question_number}"))
                item["control_work"] = control_work


